const items = $input.all();
if (items.length !== 1) throw new Error('This starter accepts exactly one input, not a recipient list.');
const c = items[0].json;
if (!/^[A-Za-z0-9_-]{1,128}$/.test(c.instance || '') || c.instance === 'YOUR_INSTANCE_ID') throw new Error('Configure your own instance.');
if (!/^[A-Za-z0-9_-]{8,256}$/.test(c.instanceToken || '') || c.instanceToken === 'YOUR_INSTANCE_TOKEN') throw new Error('Configure your own instance token privately.');
if (!/^[1-9][0-9]{9,14}$/.test(c.phone || '')) throw new Error('Use an authorized number with country code and digits only.');
if (c.authorizedRecipient !== true) throw new Error('Confirm that this recipient is yours or explicitly authorized before enabling the request.');
if (typeof c.message !== 'string' || !c.message.trim() || c.message.length > 500) throw new Error('Use a test message of 1 to 500 characters.');
return [{ json: c }];
